TROPICAL_VIOLATION_COST(n, grid, assignment):
  cost ← 0
  // Row violations
  for each row r:
    for each pair (c1, c2) with c1 ≠ c2:
      if assignment[r][c1] = assignment[r][c2]:
        cost ← cost + 1
  // Column violations (analogous)
  // Box violations (analogous)
  // Given violations
  for each cell (r,c) with grid[r][c] ≠ 0:
    if assignment[r][c] ≠ grid[r][c]:
      cost ← cost + 1
  return cost

PROPAGATE_ONCE(n, grid, state):
  for each cell c = (r, col):
    // Given restriction
    if grid[r][col] ≠ 0:
      state[c] ← state[c] ∩ {grid[r][col]}
    // Singleton elimination
    for each cell c' in same row/col/box as c:
      if c' ≠ c and |state[c']| = 1:
        state[c] ← state[c] \ state[c']
  return state

PROPAGATE_TO_CLOSURE(n, grid):
  state ← full_state(n)  // all digits for all cells
  repeat:
    new_state ← PROPAGATE_ONCE(n, grid, state)
    if new_state = state: return state
    state ← new_state
